-- ============================================================================
--  THE MODEL DATASETS                                       (Trino/Presto)
--
--  GENERATED by tools/gen_model_sql.py - do not hand-edit. Three near-identical
--  120-line blocks is where transcription errors live, and this project has
--  already lost time to a leftover date literal in one block of several. Every
--  month literal below is derived from the cohort calendars declared in that
--  script, so a wrong date is impossible rather than merely unlikely.
--
--  TARGET
--      screen  revenue at or above 170,000 Toman in 2 or more of 6 months,
--              never one-way barred and never two-way barred in that window
--      label   y = 1 if two-way barred in the 4 months IMMEDIATELY AFTER
--
--  THREE COHORTS. Data runs 140301..140506.
--
--      cohort    features        label (4 months)  role
--      TRAIN     140301..140306  140307..140310    fit
--      VALID     140401..140406  140407..140410    out of time
--      SCORE     140501..140506  none - the future hand to implementation
--
--  THE THREE WINDOWS ARE YEAR-OVER-YEAR ALIGNED, and that is the point.
--  Every feature window covers months 1-6 of its year and every label window
--  covers months 7-10, exactly 12 months apart. The generator asserts this:
--  it refuses to emit a calendar whose windows differ in length, sit at
--  different months-of-year, are unevenly spaced, or whose label reaches into
--  the next cohort's features.
--
--  WHY ALIGNMENT AND NOT PROXIMITY. An earlier version chose the windows to
--  sit as close together in time as the label allowed: TRAIN 140309..140402,
--  VALID 140407..140412, SCORE 140501..140506. That put VALID on months 7-12
--  and SCORE on months 1-6 - different seasons. Jalali month 1 is Farvardin
--  and carries Nowruz, and telco usage is strongly seasonal, so the revenue
--  features were not comparable between the window the model was judged on
--  and the window it would be applied to. VALID exists to be a rehearsal of
--  SCORE; a rehearsal in a different season is not one. That version also
--  had VALID's label window (140501..140504) overlapping SCORE's feature
--  window (140501..140506), so the period used to JUDGE the model was the
--  same period used to DESCRIBE the live population.
--
--  WHAT ALIGNMENT COSTS. TRAIN is now 24 months before SCORE rather than 8,
--  so the fixed nominal bar bites harder, not less: TRAIN at 140301..140306
--  returned 3,733,333 subscribers against the 6,879,803 measured at
--  140407..140412. That is the trade accepted here, because a drifting bar
--  is correctable - COHORT_BAR above takes a per-window threshold, and
--  43_cohort_funnel.sql D3 measures what each one should be - while a
--  seasonal mismatch cannot be corrected by any threshold.
--
--  SO THE ORDER OF WORK IS: run 43_cohort_funnel.sql, read D3 and D4, set
--  COHORT_BAR for TRAIN and VALID, regenerate this file, then fit.
--
--  NO FIGURE IS ON RECORD FOR THIS VALID WINDOW YET. The 0.95 pct measured
--  in 41_forward_horizons.sql was for features 140407..140412 with label
--  140501..140504, which is NOT a window any cohort here uses any more. The
--  new VALID is features 140401..140406 with label 140407..140410, and its
--  event rate is established by 43_cohort_funnel.sql D5. T4 reports the rate
--  rather than asserting against a number that belongs to a different
--  window - a cross-check against the wrong reference is worse than none.
--
--  PARTIAL OBSERVATION. A subscriber counts as judgeable if they appear in AT
--  LEAST ONE month of the label window - the INNER JOIN on lab enforces it,
--  and someone absent from the whole window is dropped rather than scored
--  clean, because a disappearance is not a repayment. This is deliberately
--  the same rule 41_forward_horizons.sql used (n_out_months > 0), which is
--  what makes T4's comparison against 0.95 pct meaningful. It does mean a
--  subscriber seen in 1 of 4 months and never barred is scored y = 0 on one
--  month of evidence. n_label_months is carried so that population is
--  visible and T5 reports whether it moves the rate.
--
--  EXCLUDED ON PURPOSE
--      debt_scr, suspend_scr   all zero in 6 of 10 months - their PSI of
--                              13.89 and 14.41 was a loading gap, not drift
--      month-index columns     calendar numbers that shift between windows
--                              whether or not behaviour changes
--      anything from a label window, by construction
--
--  GUARDED
--      age_on_net_months       raw range -232 to 1,285 -> clipped to 0..480
--      available_credit        raw range -3.6bn to 40.9 trillion Rial ->
--                              winsorised at 500,000,000
--      arpu                    23.8 pct NULL, and the tax is zero where arpu
--                              is NULL, so the KPI expression yields 0 rather
--                              than minus-the-tax. n_arpu_null is carried as a
--                              feature in its own right - missingness here is
--                              informative
--
--  PAYMENTS USE ALL STATUSES. bllg_pmnt_stat_id = 2 holds 61.2 pct of payment
--  value and status 1 holds 38.7 pct, so filtering to 2 discards a third.
--
--  NO percent character anywhere. NO CASE expressions.
-- ============================================================================


-- ---------------------------------------------------------------------------
-- T1  TRAIN   features 140301..140306, label 140307..140310
-- ---------------------------------------------------------------------------

DROP TABLE IF EXISTS dwbi_temp40_db.dcb_train;
CREATE TABLE dwbi_temp40_db.dcb_train WITH (format='PARQUET') AS
WITH pm AS (
    SELECT   sbrp_id, day_key / 100 AS mk, SUM(COALESCE(pmnt_amt,0)) AS paid
    FROM     dwbi_fact_db.v_fact_pmnt_adjmt
    WHERE    day_key BETWEEN 14030101 AND 14030631
    GROUP BY sbrp_id, day_key / 100
),
pay AS (
    SELECT  sbrp_id,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140301), 0) AS q1,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140302), 0) AS q2,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140303), 0) AS q3,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140304), 0) AS q4,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140305), 0) AS q5,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140306), 0) AS q6
    FROM    pm GROUP BY sbrp_id
),
feat AS (
    SELECT  sbrp_id,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140301), 0) AS r1,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140302), 0) AS r2,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140303), 0) AS r3,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140304), 0) AS r4,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140305), 0) AS r5,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140306), 0) AS r6,
            SUM(IF(arpu IS NULL, 1, 0))                      AS n_arpu_null,
            MAX(IF(month_key=140301 AND sbrp_stat_id=3,1,0)) AS o1,
            MAX(IF(month_key=140302 AND sbrp_stat_id=3,1,0)) AS o2,
            MAX(IF(month_key=140303 AND sbrp_stat_id=3,1,0)) AS o3,
            MAX(IF(month_key=140304 AND sbrp_stat_id=3,1,0)) AS o4,
            MAX(IF(month_key=140305 AND sbrp_stat_id=3,1,0)) AS o5,
            MAX(IF(month_key=140306 AND sbrp_stat_id=3,1,0)) AS o6,
            MAX(IF(sbrp_stat_id=4,1,0))                      AS f_twoway,
            MAX(IF(sbrp_stat_id IN (8,9),1,0))               AS f_reclaim,
            SUM(IF(active1_base_flag=1,1,0))                 AS n_active1,
            LEAST(MAX(COALESCE(available_credit,0)), 500000000)    AS avail_max,
            LEAST(AVG(COALESCE(available_credit,0)), 500000000)    AS avail_avg,
            LEAST(MAX(COALESCE(bill_outstanding_amt,0)), 500000000) AS outst_max,
            LEAST(AVG(COALESCE(bill_outstanding_amt,0)), 500000000) AS outst_avg,
            GREATEST(LEAST(MAX(COALESCE(age_on_net_months,0)), 480), 0) AS tenure_m
    FROM    dwbi_fact_db.v_fact_sbrp_mthly_cip
    WHERE   month_key IN (140301,140302,140303,140304,140305,140306)
      AND   sbrp_typ_id = 1
    GROUP BY sbrp_id
),
lab AS (
    SELECT   sbrp_id,
             MAX(IF(sbrp_stat_id = 4, 1, 0))  AS y,
             COUNT(DISTINCT month_key)        AS n_label_months
    FROM     dwbi_fact_db.v_fact_sbrp_mthly_cip
    WHERE    month_key IN (140307, 140308, 140309, 140310)
      AND    sbrp_typ_id = 1
    GROUP BY sbrp_id
)
SELECT  f.sbrp_id,
        f.r1, f.r2, f.r3, f.r4, f.r5, f.r6,
        f.r1+f.r2+f.r3+f.r4+f.r5+f.r6                        AS rev_6m,
        GREATEST(f.r1,f.r2,f.r3,f.r4,f.r5,f.r6)              AS rev_max,
        LEAST(f.r1,f.r2,f.r3,f.r4,f.r5,f.r6)                 AS rev_min,
        (f.r4+f.r5+f.r6) - (f.r1+f.r2+f.r3)                  AS rev_trend,
        IF(f.r1>=1700000,1,0) + IF(f.r2>=1700000,1,0) + IF(f.r3>=1700000,1,0) + IF(f.r4>=1700000,1,0) + IF(f.r5>=1700000,1,0) + IF(f.r6>=1700000,1,0)
                                                             AS rev_months,
        COALESCE(p.q1,0) AS q1, COALESCE(p.q2,0) AS q2, COALESCE(p.q3,0) AS q3,
        COALESCE(p.q4,0) AS q4, COALESCE(p.q5,0) AS q5, COALESCE(p.q6,0) AS q6,
        COALESCE(p.q1,0) + COALESCE(p.q2,0) + COALESCE(p.q3,0) + COALESCE(p.q4,0) + COALESCE(p.q5,0) + COALESCE(p.q6,0)  AS paid_6m,
        GREATEST(COALESCE(p.q1,0), COALESCE(p.q2,0), COALESCE(p.q3,0), COALESCE(p.q4,0), COALESCE(p.q5,0), COALESCE(p.q6,0)) AS paid_max,
        IF(COALESCE(p.q1,0)>=1700000,1,0) + IF(COALESCE(p.q2,0)>=1700000,1,0) + IF(COALESCE(p.q3,0)>=1700000,1,0) + IF(COALESCE(p.q4,0)>=1700000,1,0) + IF(COALESCE(p.q5,0)>=1700000,1,0) + IF(COALESCE(p.q6,0)>=1700000,1,0)
                                                             AS pay_months,
        f.o1+f.o2+f.o3+f.o4+f.o5+f.o6                        AS oneway_months,
        f.n_arpu_null, f.n_active1, f.f_reclaim,
        f.avail_max, f.avail_avg, f.outst_max, f.outst_avg, f.tenure_m,
        l.n_label_months,
        l.y,
        'TRAIN' AS cohort
FROM        feat f
LEFT JOIN   pay  p ON p.sbrp_id = f.sbrp_id
INNER JOIN  lab  l ON l.sbrp_id = f.sbrp_id
-- THE SCREEN: revenue at or above 1,700,000 Rial in 2 or more months,
-- never one-way barred, never two-way barred in the feature window.
WHERE   IF(f.r1>=1700000,1,0) + IF(f.r2>=1700000,1,0) + IF(f.r3>=1700000,1,0) + IF(f.r4>=1700000,1,0) + IF(f.r5>=1700000,1,0) + IF(f.r6>=1700000,1,0) >= 2
  AND   f.o1+f.o2+f.o3+f.o4+f.o5+f.o6 = 0
  AND   f.f_twoway = 0
;


-- ---------------------------------------------------------------------------
-- T2  VALID   features 140401..140406, label 140407..140410
-- ---------------------------------------------------------------------------

DROP TABLE IF EXISTS dwbi_temp40_db.dcb_valid;
CREATE TABLE dwbi_temp40_db.dcb_valid WITH (format='PARQUET') AS
WITH pm AS (
    SELECT   sbrp_id, day_key / 100 AS mk, SUM(COALESCE(pmnt_amt,0)) AS paid
    FROM     dwbi_fact_db.v_fact_pmnt_adjmt
    WHERE    day_key BETWEEN 14040101 AND 14040631
    GROUP BY sbrp_id, day_key / 100
),
pay AS (
    SELECT  sbrp_id,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140401), 0) AS q1,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140402), 0) AS q2,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140403), 0) AS q3,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140404), 0) AS q4,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140405), 0) AS q5,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140406), 0) AS q6
    FROM    pm GROUP BY sbrp_id
),
feat AS (
    SELECT  sbrp_id,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140401), 0) AS r1,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140402), 0) AS r2,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140403), 0) AS r3,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140404), 0) AS r4,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140405), 0) AS r5,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140406), 0) AS r6,
            SUM(IF(arpu IS NULL, 1, 0))                      AS n_arpu_null,
            MAX(IF(month_key=140401 AND sbrp_stat_id=3,1,0)) AS o1,
            MAX(IF(month_key=140402 AND sbrp_stat_id=3,1,0)) AS o2,
            MAX(IF(month_key=140403 AND sbrp_stat_id=3,1,0)) AS o3,
            MAX(IF(month_key=140404 AND sbrp_stat_id=3,1,0)) AS o4,
            MAX(IF(month_key=140405 AND sbrp_stat_id=3,1,0)) AS o5,
            MAX(IF(month_key=140406 AND sbrp_stat_id=3,1,0)) AS o6,
            MAX(IF(sbrp_stat_id=4,1,0))                      AS f_twoway,
            MAX(IF(sbrp_stat_id IN (8,9),1,0))               AS f_reclaim,
            SUM(IF(active1_base_flag=1,1,0))                 AS n_active1,
            LEAST(MAX(COALESCE(available_credit,0)), 500000000)    AS avail_max,
            LEAST(AVG(COALESCE(available_credit,0)), 500000000)    AS avail_avg,
            LEAST(MAX(COALESCE(bill_outstanding_amt,0)), 500000000) AS outst_max,
            LEAST(AVG(COALESCE(bill_outstanding_amt,0)), 500000000) AS outst_avg,
            GREATEST(LEAST(MAX(COALESCE(age_on_net_months,0)), 480), 0) AS tenure_m
    FROM    dwbi_fact_db.v_fact_sbrp_mthly_cip
    WHERE   month_key IN (140401,140402,140403,140404,140405,140406)
      AND   sbrp_typ_id = 1
    GROUP BY sbrp_id
),
lab AS (
    SELECT   sbrp_id,
             MAX(IF(sbrp_stat_id = 4, 1, 0))  AS y,
             COUNT(DISTINCT month_key)        AS n_label_months
    FROM     dwbi_fact_db.v_fact_sbrp_mthly_cip
    WHERE    month_key IN (140407, 140408, 140409, 140410)
      AND    sbrp_typ_id = 1
    GROUP BY sbrp_id
)
SELECT  f.sbrp_id,
        f.r1, f.r2, f.r3, f.r4, f.r5, f.r6,
        f.r1+f.r2+f.r3+f.r4+f.r5+f.r6                        AS rev_6m,
        GREATEST(f.r1,f.r2,f.r3,f.r4,f.r5,f.r6)              AS rev_max,
        LEAST(f.r1,f.r2,f.r3,f.r4,f.r5,f.r6)                 AS rev_min,
        (f.r4+f.r5+f.r6) - (f.r1+f.r2+f.r3)                  AS rev_trend,
        IF(f.r1>=1700000,1,0) + IF(f.r2>=1700000,1,0) + IF(f.r3>=1700000,1,0) + IF(f.r4>=1700000,1,0) + IF(f.r5>=1700000,1,0) + IF(f.r6>=1700000,1,0)
                                                             AS rev_months,
        COALESCE(p.q1,0) AS q1, COALESCE(p.q2,0) AS q2, COALESCE(p.q3,0) AS q3,
        COALESCE(p.q4,0) AS q4, COALESCE(p.q5,0) AS q5, COALESCE(p.q6,0) AS q6,
        COALESCE(p.q1,0) + COALESCE(p.q2,0) + COALESCE(p.q3,0) + COALESCE(p.q4,0) + COALESCE(p.q5,0) + COALESCE(p.q6,0)  AS paid_6m,
        GREATEST(COALESCE(p.q1,0), COALESCE(p.q2,0), COALESCE(p.q3,0), COALESCE(p.q4,0), COALESCE(p.q5,0), COALESCE(p.q6,0)) AS paid_max,
        IF(COALESCE(p.q1,0)>=1700000,1,0) + IF(COALESCE(p.q2,0)>=1700000,1,0) + IF(COALESCE(p.q3,0)>=1700000,1,0) + IF(COALESCE(p.q4,0)>=1700000,1,0) + IF(COALESCE(p.q5,0)>=1700000,1,0) + IF(COALESCE(p.q6,0)>=1700000,1,0)
                                                             AS pay_months,
        f.o1+f.o2+f.o3+f.o4+f.o5+f.o6                        AS oneway_months,
        f.n_arpu_null, f.n_active1, f.f_reclaim,
        f.avail_max, f.avail_avg, f.outst_max, f.outst_avg, f.tenure_m,
        l.n_label_months,
        l.y,
        'VALID' AS cohort
FROM        feat f
LEFT JOIN   pay  p ON p.sbrp_id = f.sbrp_id
INNER JOIN  lab  l ON l.sbrp_id = f.sbrp_id
-- THE SCREEN: revenue at or above 1,700,000 Rial in 2 or more months,
-- never one-way barred, never two-way barred in the feature window.
WHERE   IF(f.r1>=1700000,1,0) + IF(f.r2>=1700000,1,0) + IF(f.r3>=1700000,1,0) + IF(f.r4>=1700000,1,0) + IF(f.r5>=1700000,1,0) + IF(f.r6>=1700000,1,0) >= 2
  AND   f.o1+f.o2+f.o3+f.o4+f.o5+f.o6 = 0
  AND   f.f_twoway = 0
;


-- ---------------------------------------------------------------------------
-- T3  SCORE   features 140501..140506, NO LABEL - the outcome is the future
-- ---------------------------------------------------------------------------

DROP TABLE IF EXISTS dwbi_temp40_db.dcb_score;
CREATE TABLE dwbi_temp40_db.dcb_score WITH (format='PARQUET') AS
WITH pm AS (
    SELECT   sbrp_id, day_key / 100 AS mk, SUM(COALESCE(pmnt_amt,0)) AS paid
    FROM     dwbi_fact_db.v_fact_pmnt_adjmt
    WHERE    day_key BETWEEN 14050101 AND 14050631
    GROUP BY sbrp_id, day_key / 100
),
pay AS (
    SELECT  sbrp_id,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140501), 0) AS q1,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140502), 0) AS q2,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140503), 0) AS q3,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140504), 0) AS q4,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140505), 0) AS q5,
            COALESCE(SUM(paid) FILTER (WHERE mk = 140506), 0) AS q6
    FROM    pm GROUP BY sbrp_id
),
feat AS (
    SELECT  sbrp_id,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140501), 0) AS r1,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140502), 0) AS r2,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140503), 0) AS r3,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140504), 0) AS r4,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140505), 0) AS r5,
            COALESCE(SUM(COALESCE(arpu,0)-COALESCE(tot_arpu_tax_amt,0))
                     FILTER (WHERE month_key = 140506), 0) AS r6,
            SUM(IF(arpu IS NULL, 1, 0))                      AS n_arpu_null,
            MAX(IF(month_key=140501 AND sbrp_stat_id=3,1,0)) AS o1,
            MAX(IF(month_key=140502 AND sbrp_stat_id=3,1,0)) AS o2,
            MAX(IF(month_key=140503 AND sbrp_stat_id=3,1,0)) AS o3,
            MAX(IF(month_key=140504 AND sbrp_stat_id=3,1,0)) AS o4,
            MAX(IF(month_key=140505 AND sbrp_stat_id=3,1,0)) AS o5,
            MAX(IF(month_key=140506 AND sbrp_stat_id=3,1,0)) AS o6,
            MAX(IF(sbrp_stat_id=4,1,0))                      AS f_twoway,
            MAX(IF(sbrp_stat_id IN (8,9),1,0))               AS f_reclaim,
            SUM(IF(active1_base_flag=1,1,0))                 AS n_active1,
            LEAST(MAX(COALESCE(available_credit,0)), 500000000)    AS avail_max,
            LEAST(AVG(COALESCE(available_credit,0)), 500000000)    AS avail_avg,
            LEAST(MAX(COALESCE(bill_outstanding_amt,0)), 500000000) AS outst_max,
            LEAST(AVG(COALESCE(bill_outstanding_amt,0)), 500000000) AS outst_avg,
            GREATEST(LEAST(MAX(COALESCE(age_on_net_months,0)), 480), 0) AS tenure_m
    FROM    dwbi_fact_db.v_fact_sbrp_mthly_cip
    WHERE   month_key IN (140501,140502,140503,140504,140505,140506)
      AND   sbrp_typ_id = 1
    GROUP BY sbrp_id
)
SELECT  f.sbrp_id,
        f.r1, f.r2, f.r3, f.r4, f.r5, f.r6,
        f.r1+f.r2+f.r3+f.r4+f.r5+f.r6                        AS rev_6m,
        GREATEST(f.r1,f.r2,f.r3,f.r4,f.r5,f.r6)              AS rev_max,
        LEAST(f.r1,f.r2,f.r3,f.r4,f.r5,f.r6)                 AS rev_min,
        (f.r4+f.r5+f.r6) - (f.r1+f.r2+f.r3)                  AS rev_trend,
        IF(f.r1>=1700000,1,0) + IF(f.r2>=1700000,1,0) + IF(f.r3>=1700000,1,0) + IF(f.r4>=1700000,1,0) + IF(f.r5>=1700000,1,0) + IF(f.r6>=1700000,1,0)
                                                             AS rev_months,
        COALESCE(p.q1,0) AS q1, COALESCE(p.q2,0) AS q2, COALESCE(p.q3,0) AS q3,
        COALESCE(p.q4,0) AS q4, COALESCE(p.q5,0) AS q5, COALESCE(p.q6,0) AS q6,
        COALESCE(p.q1,0) + COALESCE(p.q2,0) + COALESCE(p.q3,0) + COALESCE(p.q4,0) + COALESCE(p.q5,0) + COALESCE(p.q6,0)  AS paid_6m,
        GREATEST(COALESCE(p.q1,0), COALESCE(p.q2,0), COALESCE(p.q3,0), COALESCE(p.q4,0), COALESCE(p.q5,0), COALESCE(p.q6,0)) AS paid_max,
        IF(COALESCE(p.q1,0)>=1700000,1,0) + IF(COALESCE(p.q2,0)>=1700000,1,0) + IF(COALESCE(p.q3,0)>=1700000,1,0) + IF(COALESCE(p.q4,0)>=1700000,1,0) + IF(COALESCE(p.q5,0)>=1700000,1,0) + IF(COALESCE(p.q6,0)>=1700000,1,0)
                                                             AS pay_months,
        f.o1+f.o2+f.o3+f.o4+f.o5+f.o6                        AS oneway_months,
        f.n_arpu_null, f.n_active1, f.f_reclaim,
        f.avail_max, f.avail_avg, f.outst_max, f.outst_avg, f.tenure_m,
        CAST(NULL AS BIGINT) AS n_label_months,
        CAST(NULL AS INTEGER) AS y,
        'SCORE' AS cohort
FROM        feat f
LEFT JOIN   pay  p ON p.sbrp_id = f.sbrp_id
-- THE SCREEN: revenue at or above 1,700,000 Rial in 2 or more months,
-- never one-way barred, never two-way barred in the feature window.
WHERE   IF(f.r1>=1700000,1,0) + IF(f.r2>=1700000,1,0) + IF(f.r3>=1700000,1,0) + IF(f.r4>=1700000,1,0) + IF(f.r5>=1700000,1,0) + IF(f.r6>=1700000,1,0) >= 2
  AND   f.o1+f.o2+f.o3+f.o4+f.o5+f.o6 = 0
  AND   f.f_twoway = 0
;


-- ---------------------------------------------------------------------------
-- T4  CHECK BEFORE EXPORTING ANYTHING.
--
--     Compare VALID's rate against 43_cohort_funnel.sql D5 for window
--     140401..140406, which is the figure of record for THIS window. Do not
--     compare it against the 0.95 pct from 41_forward_horizons.sql: that was
--     measured on features 140407..140412 with label 140501..140504, a
--     different window in a different season, and the two are not
--     interchangeable.
--
--     Also compare the three row counts. If TRAIN and VALID are far below
--     SCORE, the fixed nominal bar is still selecting the richer tail in the
--     earlier windows and COHORT_BAR has not been set from D3 yet.
-- ---------------------------------------------------------------------------
SELECT  'TRAIN' AS cohort, COUNT(*) AS n, SUM(y) AS n_bad,
        100.0 * SUM(y) / COUNT(*) AS bad_pct,
        APPROX_PERCENTILE(rev_6m, 0.5) / 10000 AS med_rev_6m_k,
        APPROX_PERCENTILE(CAST(rev_months AS DOUBLE), 0.5) AS med_rev_months
FROM    dwbi_temp40_db.dcb_train
UNION ALL
SELECT  'VALID', COUNT(*), SUM(y), 100.0 * SUM(y) / COUNT(*),
        APPROX_PERCENTILE(rev_6m, 0.5) / 10000,
        APPROX_PERCENTILE(CAST(rev_months AS DOUBLE), 0.5)
FROM    dwbi_temp40_db.dcb_valid
UNION ALL
SELECT  'SCORE', COUNT(*), NULL, NULL,
        APPROX_PERCENTILE(rev_6m, 0.5) / 10000,
        APPROX_PERCENTILE(CAST(rev_months AS DOUBLE), 0.5)
FROM    dwbi_temp40_db.dcb_score;

-- Subscribers shared between cohorts is expected and fine - the same person
-- appears in all three with different windows. What must not happen is a
-- feature window touching its own label window, and the generator makes that
-- impossible.
SELECT  (SELECT COUNT(*) FROM dwbi_temp40_db.dcb_train t
          INNER JOIN dwbi_temp40_db.dcb_valid v ON v.sbrp_id = t.sbrp_id)
                                                        AS train_valid_shared,
        (SELECT COUNT(*) FROM dwbi_temp40_db.dcb_valid v
          INNER JOIN dwbi_temp40_db.dcb_score s ON s.sbrp_id = v.sbrp_id)
                                                        AS valid_score_shared;

-- ---------------------------------------------------------------------------
-- T5  DOES PARTIAL OBSERVATION MOVE THE RATE? Over a 4-month label window a
--     subscriber can be present for only part of it. Those rows are kept (see
--     the header), so this asks what they are worth: the rate among the fully
--     observed against the rate among the partly observed.
--
--     If the fully-observed rate is materially HIGHER, the headline rate is
--     diluted by subscribers who simply had less time to fail, and the
--     fully-observed figure is the honest one to quote to the business.
-- ---------------------------------------------------------------------------
SELECT  cohort,
        n_label_months,
        COUNT(*)                                        AS n,
        SUM(y)                                          AS n_bad,
        100.0 * SUM(y) / COUNT(*)                       AS bad_pct
FROM    (SELECT cohort, n_label_months, y FROM dwbi_temp40_db.dcb_train
         UNION ALL
         SELECT cohort, n_label_months, y FROM dwbi_temp40_db.dcb_valid) u
GROUP BY cohort, n_label_months
ORDER BY cohort, n_label_months;

SELECT  cohort,
        SUM(IF(n_label_months = 4, 1, 0))               AS n_full,
        100.0 * SUM(IF(n_label_months = 4, y, 0))
              / NULLIF(SUM(IF(n_label_months = 4, 1, 0)), 0)
                                                        AS bad_pct_full,
        SUM(IF(n_label_months < 4, 1, 0))               AS n_partial,
        100.0 * SUM(IF(n_label_months < 4, y, 0))
              / NULLIF(SUM(IF(n_label_months < 4, 1, 0)), 0)
                                                        AS bad_pct_partial,
        100.0 * SUM(IF(n_label_months < 4, 1, 0)) / COUNT(*)
                                                        AS partial_share_pct
FROM    (SELECT cohort, n_label_months, y FROM dwbi_temp40_db.dcb_train
         UNION ALL
         SELECT cohort, n_label_months, y FROM dwbi_temp40_db.dcb_valid) u
GROUP BY cohort
ORDER BY cohort;
